const uint64 Before=Field.GeometryRevision; Field.NativeAux.Add(FIntPoint(0,0),.02f); Field.StepNative();
TestTrue(TEXT("Native cut changes the physical bed"),Field.Read(FIntPoint(0,0)).DeltaCm<-.1f);
TestTrue(TEXT("Native batch notifies water and shadows"),Field.GeometryRevision>Before);
TArray<FBox2D> Regions; Field.BedChangesSince(Before,Regions); bool Found=false; for(const auto& R:Regions)Found|=R.IsInside(Field.Centre(FIntPoint(0,0)));
TestTrue(TEXT("Changed bed region contains the cut"),Found); const uint64 After=Field.GeometryRevision; Field.StepNative();
TestTrue(TEXT("Idle native step does not invalidate the bed"),Field.GeometryRevision==After);
